function overviewTickers(){getSim();const r=selected(),rows=r.weights.map((w,id)=>({w,id,a:sim.assets[id]})).filter(x=>x.w>0).sort((a,b)=>b.w-a.w).slice(0,6);return `<section class="panel opportunity-panel section-gap"><div><span class="eyebrow">TỪ PHƯƠNG PHÁP ĐẾN CÁC MÃ CỤ THỂ</span><h2>Danh mục đang chọn · ${S.market==='VN'?'Việt Nam':'Hoa Kỳ'}</h2><p>Nhập vốn để xem số tiền phân bổ theo từng cổ phiếu.</p><button class="btn primary" data-action="go-allocation">Thiết lập phân bổ vốn ${I('arrow')}</button></div><div class="opportunity-tickers">${rows.map(o=>`<button data-action="stock" data-value="${o.id}" data-key="${S.market}" data-date="${r.endDate}"><span class="stock-avatar" style="color:${E.COLORS[o.a[2]]};background:${E.COLORS[o.a[2]]}15">${o.a[0].slice(0,2)}</span><span><strong>${o.a[0]}</strong><small>${o.a[1]}</small></span><b>${pct(o.w)}</b></button>`).join('')}</div></section>`;}
function help(){
 $('helpBody').innerHTML=V2.lang==='en'?`<h3>Data and scope</h3><p>Published results are transcribed from Tables 4.1, 4.2, 4.4 and 4.5 in the supplied research paper. They remain independent of portfolio inputs.</p><p>Interactive portfolio, allocation, stock charts and technical indicators use synthetic research data, not historical prices or a live market feed. The regime selector is rule-based and does not execute the paper’s trained D3QN checkpoint. PSO/HRP allocators use reduced configurations; the shrinkage branch uses a fixed coefficient.</p><h3>Capital allocation</h3><p>Stock budgets, cash and estimated fees reconcile exactly to the entered capital. No market prices, order quantities, fills, news counts or real model confidence scores are fabricated. Allocation output describes a research scenario, not a live trading recommendation.</p><h3>Metrics and constraints</h3><p>Daily returns are annualized using 252 sessions. NAV is rebased to 100 for the selected window. SRPerf uses geometric annual return; bootstrap intervals concern SRBoot based on arithmetic daily returns. An interval above zero is not a pairwise superiority test.</p><p>Turnover uses the full target-weight union without a half factor. Transaction costs are 0.001 × turnover, deducted at the start of each block. Interactive benchmarks exclude explicit costs. Stock indicators use cumulative indices rather than quoted prices. The internal sentiment score covers four available components; news and actual fund flows remain unconnected.</p>`:`<h3>Nguồn dữ liệu và phạm vi sử dụng</h3><p><strong>Kết quả công bố</strong> được trích từ Bảng 4.1, 4.2, 4.4 và 4.5 trong bản toàn văn. Các số này độc lập với số tiền và cấu hình người xem nhập. Giai đoạn lấy dữ liệu của nghiên cứu: 01/01/2010–24/03/2026; không đồng nhất với mọi cửa sổ OOS.</p><p><strong>Các màn hình tương tác sử dụng dữ liệu tổng hợp theo kịch bản nghiên cứu</strong>, không kết nối giá lịch sử hay bảng giá trực tiếp. Bộ chọn chế độ dùng quy tắc xác định, không chạy checkpoint D3QN đã huấn luyện trong bài. PSO/HRP dùng cấu hình rút gọn; nhánh co rút dùng hệ số cố định 35%.</p><h3>Phân bổ vốn và danh sách mã</h3><p>D3QN trong kiến trúc nghiên cứu chọn chế độ, không trực tiếp khuyến nghị từng mã. Tập mã được xếp hạng theo động lượng và chuyển cho bộ phân bổ. Trang Phân bổ vốn dùng trọng số và giới hạn người xem chọn để tính ngân sách cho từng cổ phiếu; không cung cấp giá đặt lệnh, số cổ phiếu khớp lệnh hay khẳng định đây là khuyến nghị giao dịch thực tế.</p><p>Ngân sách cổ phiếu + tiền mặt + chi phí bằng vốn nhập. Phí 0,10% được dự phòng trước khi phân bổ; số tiền theo mã được làm tròn theo đơn vị tiền tệ bằng quy tắc phần dư lớn nhất. Khi thay đổi thiết lập, phải bấm Phân tích & phân bổ để áp dụng.</p><h3>Danh mục và chỉ báo</h3><p>Chuỗi tổng hợp theo ngày trong tuần từ 02/01/2020 đến 24/03/2026, chưa loại trừ ngày lễ. Trọng số mục tiêu giữ cố định trong từng khối. Turnover tính trên toàn bộ tập trọng số trước/sau, không chia 2; phí 0,001 × turnover trừ vào ngày đầu khối. Quy ước này khác TO trên tập tài sản hoạt động trong nghiên cứu. Benchmark tương tác chưa khấu trừ phí.</p><p>Biểu đồ từng mã dùng chỉ số tích lũy gốc 100, không phải giá niêm yết. RSI và MACD tính từ chỉ số tích lũy; các chỉ báo không phải nguồn tin doanh nghiệp. Chỉ số tâm lý nội bộ dùng động lượng, RSI, độ rộng và biến động. Nguồn tin tức và dòng tiền giao dịch chưa kết nối, vì vậy các ô liên quan để trống thay vì tạo số bài báo.</p><div class="formula">NAVₜ = NAVₜ₋₁ × (1 + rₜ)<br>AR = (NAV cuối / NAV đầu)^(252/N) − 1<br>σ năm = sd(r ngày) × √252<br>SRPerf = AR / σ năm<br>Calmar = AR / |Max drawdown|</div><h3>Đối chiếu và suy luận</h3><p>SRBoot dùng trung bình số học của lợi nhuận ngày, khác SRPerf. KTC 95% từ bootstrap i.i.d. 1.000 lần không phải dải sai số quanh SRPerf và không thay thế kiểm định theo cặp. Hai thị trường có khác biệt đặc tả phần thưởng và dữ liệu; so sánh có tính mô tả, không quy toàn bộ chênh lệch cho cấu trúc thị trường.</p><p>Dữ liệu nghiên cứu còn hạn chế về thiên lệch sống sót, xử lý thiếu dữ liệu, điều chỉnh giá, chi phí và tần suất lưu NAV. MinVar Việt Nam là chẩn đoán hậu nghiệm; cơ chế dự phòng Hoa Kỳ không kích hoạt trong OOS đã lưu. Nguồn: Chương 3, Bảng 4.3, 4.6 và mục 5.3.</p><h3>Thao tác</h3><p>Nhập vốn, cấu hình tập mã rồi bấm Phân tích & phân bổ. Chạm mã để xem chi tiết. Tại Danh mục & hiệu quả, phát lại theo kỳ, Ctrl + cuộn để thu/phóng, kéo ngang để di chuyển cửa sổ; nhấp đúp để về toàn kỳ. Nút trình chiếu ở góc trên; Esc thoát. Có thể xuất CSV và chuyển VI/EN.</p>`;
 $('helpDialog').showModal();
}
function v2Act(action,value,el){
 if(action==='plan-market'){S.market=value;S.cursor=-1;V2.error='';render();return true;}
 if(action==='plan-horizon'){S.horizon=Number(value);S.cursor=-1;V2.error='';render();return true;}
 if(action==='plan-capital'){S.capital[S.market]=Number(value);render();return true;}
 if(action==='plan-exclude'){const a=V2.excluded[S.market],at=a.indexOf(value);if(at<0)a.push(value);else a.splice(at,1);render();return true;}
 if(action==='plan-export'){exportPlan();return true;}
 if(action==='stock'){stockDetail(el.dataset.key||S.market,Number(value),el.dataset.date||selected().endDate);return true;}
 if(action==='close-stock'){$('stockDialog').close();return true;}
 if(action==='analysis-tab'){V2.tab=value;render();return true;}
 if(action==='compare-mode'){V2.compareMode=value;render();return true;}
 if(action==='language'){V2.lang=V2.lang==='vi'?'en':'vi';document.documentElement.lang=V2.lang;render();return true;}
 if(action==='chart-reset'){S.window=0;render();return true;}
 return false;
}
document.addEventListener('submit',e=>{if(e.target.id==='allocationForm'){e.preventDefault();runPlan();}});
document.addEventListener('input',e=>{if(e.target.dataset.field==='pCapital'){S.capital[S.market]=Number(e.target.value);const status=document.querySelector('.plan-result-top .tag');if(status){status.textContent='Tham số chưa áp dụng';status.className='tag amber';}}if(e.target.id==='planSearch')filterPlan();if(e.target.dataset.field==='pReserve'){e.target.nextElementSibling.textContent=e.target.value+'%';}});
document.addEventListener('change',e=>{const t=e.target,k=t.dataset.field;if(t.id==='planSector'){filterPlan();return;}if(!k?.startsWith('p'))return;V2.error='';if(k==='pCapital'){S.capital[S.market]=Number(t.value);return;}if(k==='pMode'){S.mode=t.value;S.cursor=-1;}if(k==='pCount')V2.count=Number(t.value);if(k==='pCap')V2.cap=Number(t.value);if(k==='pReserve')V2.reserve=Number(t.value);render();});
document.addEventListener('pointerdown',e=>{const c=e.target.closest('[data-chart="nav"]');S.chartDragged=false;if(c&&viewData&&e.button===0)V2.drag={x:e.clientX,cursor:S.cursor,days:viewData.rows.length,width:c.getBoundingClientRect().width};});
document.addEventListener('pointerup',e=>{const a=V2.drag;V2.drag=null;if(!a||Math.abs(e.clientX-a.x)<8||S.window===0)return;const delta=Math.round((e.clientX-a.x)/a.width*a.days/S.horizon);stop();S.cursor=Math.max(0,Math.min(sim.records.length-1,a.cursor-delta));S.chartDragged=true;render();});
document.addEventListener('wheel',e=>{if(!e.ctrlKey||!e.target.closest('[data-chart="nav"]')||!viewData)return;e.preventDefault();S.window=Math.max(20,Math.min(viewData.end+1,Math.round(viewData.rows.length*(e.deltaY>0?1.3:.75))));render();},{passive:false});
document.addEventListener('dblclick',e=>{if(e.target.closest('[data-chart="nav"]')){S.window=0;render();}});
